HWND visible_rc10_dialog(DWORD pid){struct Find{DWORD pid;HWND h{};} found{pid};EnumWindows([](HWND h,LPARAM raw)->BOOL{auto& f=*reinterpret_cast<Find*>(raw);DWORD p{};GetWindowThreadProcessId(h,&p);wchar_t name[64]{};GetClassNameW(h,name,64);if(p==f.pid&&IsWindowVisible(h)&&std::wstring(name)==L"#32770"){f.h=h;return FALSE;}return TRUE;},reinterpret_cast<LPARAM>(&found));return found.h;}
HWND wait_rc10_dialog(DWORD pid){HWND h{};const auto end=GetTickCount64()+10000;while(!h&&GetTickCount64()<end){h=visible_rc10_dialog(pid);Sleep(20);}check(h!=nullptr,"owned visible modal dialog");return h;}
std::wstring selected_label(HWND list){const auto n=SendMessageW(list,LB_GETCURSEL,0,0);wchar_t text[512]{};check(n!=LB_ERR&&SendMessageW(list,LB_GETTEXT,n,reinterpret_cast<LPARAM>(text))!=LB_ERR,"selected native list text");return text;}
int main(int argc,char** argv){Product config,panel;try{
 const bool online=argc==3&&std::string(argv[2])=="--online";check(argc==2||online,"fresh RC10 shipping UI output");const auto out=std::filesystem::absolute(argv[1]);check(!std::filesystem::exists(out),"retain UI evidence");std::filesystem::create_directories(out);
 const auto tag=out.filename().native();const auto group_key="RC10 Shipping check "+out.filename().string();const auto group_name=L"RC10 Shipping check "+tag;
 const auto root=win32::installation::canonical_root(L"C:/Program Files/SFX-OwnerFixes-Test-20261031-r3");const auto owner=win32::current_process_user_sid_string();check(!win32::installation::elevated(),"normal user shipping test");win32::installation::verify_runtime_installation(root,owner);
 if(online){panel=launch(root/L"Bin/SFXControlPanel.exe",L"");panel.window=wait_window(panel.pid,kWindowClass);const auto end=GetTickCount64()+20000;while(!visible_text_contains(panel.window,L"READY")&&GetTickCount64()<end)Sleep(20);check(visible_text_contains(panel.window,L"READY"),"current installed Runtime ready");}
 config=launch(root/L"Bin/SFXConfig.exe",L"");config.window=wait_window(config.pid,L"SFXConfigWindow");
 const auto control=[&](int id){HWND h{};const auto end=GetTickCount64()+15000;while(!h&&GetTickCount64()<end){h=visible_control(config.window,id);Sleep(20);}check(h!=nullptr,("visible RC10 control "+std::to_string(id)).c_str());return h;};
 const auto click=[&](int id){DWORD_PTR result{};check(SendMessageTimeoutW(control(id),BM_CLICK,0,0,SMTO_ABORTIFHUNG,30000,&result)!=0,"shipping Config action completed");};
 const auto set=[&](int id,const wchar_t* value){check(set_foreign_text(control(id),value),"shipping field input exact");};
 const auto nav=control(1001);auto category=TreeView_GetRoot(nav);category=TreeView_GetNextSibling(nav,category);category=TreeView_GetNextSibling(nav,category);check(TreeView_SelectItem(nav,TreeView_GetChild(nav,category))!=FALSE,"navigate Files Groups and Areas");control(IDC_FILE_NEW_GROUP);
 click(IDC_FILE_NEW_GROUP);check(foreign_text(control(IDC_FILE_NAME_LABEL))==L"Group Name","shipping Group label");set(IDC_FILE_NAME,group_name.c_str());click(IDC_FILE_SAVE);check(selected_label(control(IDC_FILE_GROUPS)).find(L"RC10 Shipping check")!=std::wstring::npos,"new Group remains selected after Save");
 const auto add=[&](const wchar_t* name,const wchar_t* folder,bool insert){const auto path=root/L"Files"/(std::wstring(folder)+L"-"+tag);check(CreateDirectoryW(path.c_str(),nullptr)!=FALSE,"ordinary inherited fixture folder created");click(insert?IDC_FILE_INSERT_AFTER:IDC_FILE_NEW_AREA);check(foreign_text(control(IDC_FILE_NAME_LABEL))==L"Area Name","shipping New Area/Insert switches label");set(IDC_FILE_NAME,name);set(IDC_FILE_PATH,path.c_str());set(IDC_FILE_ACCESS,L"10");set(IDC_FILE_UPLOAD,L"999");set(IDC_FILE_DOWNLOAD,L"10");click(IDC_FILE_SAVE);check(selected_label(control(IDC_FILE_AREAS)).find(name)!=std::wstring::npos,"inherited-folder Save completes and Area remains selected");};
 add(L"RC10 First",L"RC10-First",false);add(L"RC10 Second",L"RC10-Second",true);check(SendMessageW(control(IDC_FILE_AREAS),LB_GETCOUNT,0,0)==2,"two shipping Areas saved");click(IDC_FILE_MOVE_UP);check(SendMessageW(control(IDC_FILE_AREAS),LB_GETCURSEL,0,0)==0,"shipping Move Up selects new position");click(IDC_FILE_MOVE_DOWN);check(SendMessageW(control(IDC_FILE_AREAS),LB_GETCURSEL,0,0)==1,"shipping Move Down retains identity");render_foreign_png(config.window,out/L"areas-order-and-label.png");
 if(online){PostMessageW(control(IDC_FILE_DELETE_GROUP),BM_CLICK,0,0);const auto refused=wait_rc10_dialog(config.pid);check(visible_text_contains(refused,L"Stop the BBS and close File Manager"),"online deletion has actionable stopped-BBS guard");PostMessageW(refused,WM_COMMAND,IDOK,0);PostMessageW(config.window,WM_CLOSE,0,0);check(WaitForSingleObject(config.process.get(),20000)==WAIT_OBJECT_0,"online Config closes without unsaved loop");config.window=nullptr;close_panel(panel);const auto saved=win32::offline_file_configuration_catalog(root,owner);check(saved&&saved.value,"online changes survive Runtime shutdown");auto found=std::find_if(saved.value->groups.begin(),saved.value->groups.end(),[&](const auto& g){return g.name==group_key;});check(found!=saved.value->groups.end(),"actual owner relay saved Group");unsigned count{};for(const auto& a:saved.value->areas)if(a.area.group==found->id){++count;check(a.area.permissions.access==10&&a.area.permissions.upload==999&&a.area.permissions.download==10,"online inherited folder requirements persist");}check(count==2,"online Insert/Move saved both Areas");std::cout<<"PASS RC10 online shipping Config "<<checks<<" checks: real Runtime relay, inherited folders, labels, insertion/order, deletion guard and durable restart\n";return 0;}
 // Exercise actual default-Cancel choice and then explicit keep-files confirmation.
 PostMessageW(control(IDC_FILE_DELETE_GROUP),BM_CLICK,0,0);const auto dialog=wait_rc10_dialog(config.pid);check(foreign_text(dialog)==L"Delete File Group","actual deletion chooser visible");Sleep(250);render_foreign_png(dialog,out/L"delete-group-warning.png");SendMessageW(dialog,TDM_CLICK_BUTTON,IDCANCEL,0);check(SendMessageW(control(IDC_FILE_AREAS),LB_GETCOUNT,0,0)==2,"cancel leaves Areas intact");
 PostMessageW(control(IDC_FILE_DELETE_GROUP),BM_CLICK,0,0);auto chooser=wait_rc10_dialog(config.pid);PostMessageW(chooser,TDM_CLICK_BUTTON,101,0);HWND confirm{};const auto end=GetTickCount64()+10000;while(GetTickCount64()<end){auto h=visible_rc10_dialog(config.pid);if(h&&GetDlgItem(h,IDYES)){confirm=h;break;}Sleep(20);}check(confirm!=nullptr,"explicit second confirmation");PostMessageW(confirm,WM_COMMAND,IDYES,0);
 const auto finished=GetTickCount64()+30000;while(GetTickCount64()<finished&&!visible_text_contains(config.window,L"Files on disk were kept"))Sleep(20);check(visible_text_contains(config.window,L"Files on disk were kept"),"actual offline shipping Group deletion finishes with useful result");render_foreign_png(config.window,out/L"group-removed-files-kept.png");
 PostMessageW(config.window,WM_CLOSE,0,0);check(WaitForSingleObject(config.process.get(),20000)==WAIT_OBJECT_0,"shipping Config closes without unsaved loop");config.window=nullptr;
 const auto state=win32::offline_file_configuration_catalog(root,owner);check(state&&state.value,"saved shipping catalog readable");for(const auto& g:state.value->groups)check(g.name!=group_key,"deleted Group absent after reopen");
 std::cout<<"PASS RC10 shipping Config "<<checks<<" checks: ordinary inherited-folder Save, labels, Insert After, Move Up/Down, deletion cancel/warning/keep-files and reopen; synthetic installed fixture only\n";return 0;
}catch(const std::exception& e){if(config.window){PostMessageW(config.window,WM_CLOSE,0,0);WaitForSingleObject(config.process.get(),20000);}try{close_panel(panel);}catch(...){}std::cerr<<"FAIL RC10 shipping Config "<<checks<<": "<<e.what()<<'\n';return 1;}}
